package com.dominik.cardvault.security

import java.net.URI

/** A RAM-only snapshot, not a token provider. Reading it cannot initiate network work. */
internal class CachedAppCheckHeader(private val nowMillis: () -> Long = System::currentTimeMillis) {
    // Not a data class: autogenerated toString must never contain credentials.
    private class Snapshot(val token: String, val expiresAt: Long, val observedAt: Long)
    @Volatile private var snapshot: Snapshot? = null

    fun update(token: String, expiresAtMillis: Long) {
        val now = nowMillis()
        snapshot = if (token.length <= MAX_TOKEN_LENGTH && TOKEN_FORMAT.matches(token) &&
            now >= 0 && expiresAtMillis > now && expiresAtMillis - now > EXPIRY_MARGIN_MILLIS
        ) Snapshot(token, expiresAtMillis, now) else null
    }

    fun clear() { snapshot = null }

    fun forRequest(method: String, url: String): String? {
        if (!allowedRequest(method, url)) return null
        val current = snapshot ?: return null
        val now = nowMillis()
        // A backward wall-clock change must not extend the lifetime of a cached credential.
        if (now < current.observedAt || current.expiresAt <= now ||
            current.expiresAt - now <= EXPIRY_MARGIN_MILLIS) return null
        return current.token
    }

    companion object {
        const val HEADER = "X-Firebase-AppCheck"
        private const val MAX_TOKEN_LENGTH = 4_096
        private const val EXPIRY_MARGIN_MILLIS = 60_000L
        private val TOKEN_FORMAT = Regex("[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+\\.[A-Za-z0-9_-]+")

        private fun allowedRequest(method: String, url: String): Boolean {
            val uri = try { URI(url) } catch (_: Exception) { return false }
            if (uri.scheme != "https" || uri.host != "domidex.web.app" ||
                (uri.port != -1 && uri.port != 443) || uri.rawUserInfo != null || uri.rawFragment != null) return false
            return when (uri.rawPath) {
                "/api/binder-shares" -> method == "GET" || method == "POST" || method == "DELETE"
                "/api/pretester/scan-reports", "/api/scanner/reviewed-knowledge" -> method == "POST"
                else -> false
            }
        }
    }
}

/** Disabled rollout does not even instantiate the SDK/provider. No suspend, await or refresh. */
internal fun startAppCheckIfEnabled(enabled: Boolean, install: () -> Unit) {
    if (enabled) install()
}
